import java.util.*;

public class Main {
    static int ongkir(Kirim k) {
        if (k instanceof Kurir) {
            Kurir c = (Kurir) k;
            return c.jarakKm() * 2000;
        }
        if (k instanceof Ambil) {
            return 0;
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().trim().split(" ");
            Kirim k = d[0].equals("ambil") ? new Ambil(d[1]) : new Kurir(Integer.parseInt(d[1]), d.length > 2 && d[2].equals("ekspres"));
            System.out.println(String.join(" ", d) + " -> " + ongkir(k));
        }
    }
}

sealed interface Kirim permits Kurir, Ambil {}

record Kurir(int jarakKm, boolean ekspres) implements Kirim {}

record Ambil(String cabang) implements Kirim {}

